const H = this.helpers;
const req = {
  SHOPIFY_STORE_DOMAIN: $env.SHOPIFY_STORE_DOMAIN,
  SHOPIFY_CLIENT_ID: $env.SHOPIFY_CLIENT_ID,
  SHOPIFY_CLIENT_SECRET: $env.SHOPIFY_CLIENT_SECRET,
  SHOPIFY_API_VERSION: $env.SHOPIFY_API_VERSION,
  TELEGRAM_BOT_TOKEN: $env.TELEGRAM_BOT_TOKEN,
  TELEGRAM_APPROVALS_CHAT_ID: $env.TELEGRAM_APPROVALS_CHAT_ID,
  OPENAI_API_KEY: $env.OPENAI_API_KEY,
  PRINTFUL_API_KEY: $env.PRINTFUL_API_KEY,
  SUPABASE_URL: $env.SUPABASE_URL,
  SUPABASE_SERVICE_ROLE_KEY: $env.SUPABASE_SERVICE_ROLE_KEY,
};
const missingEnv = Object.keys(req).filter((k) => !req[k]);
const dom = req.SHOPIFY_STORE_DOMAIN;
const ver = req.SHOPIFY_API_VERSION || '2025-07';
let webhookCount = null;
async function check(service, fn) {
  const t0 = Date.now();
  try { const d = await fn(); return { service, status: 'ok', detail: (d == null ? '' : String(d)).slice(0, 300), latency: Date.now() - t0 }; }
  catch (e) { const m = e && (e.message || e.description) ? (e.message || e.description) : String(e); return { service, status: 'error', detail: String(m).slice(0, 300), latency: Date.now() - t0 }; }
}
const results = [];
results.push(await check('shopify', async () => {
  if (!dom || !req.SHOPIFY_CLIENT_ID || !req.SHOPIFY_CLIENT_SECRET) throw new Error('variables Shopify manquantes');
  const tok = await H.httpRequest({ method: 'POST', url: `https://${dom}/admin/oauth/access_token`, body: { grant_type: 'client_credentials', client_id: req.SHOPIFY_CLIENT_ID, client_secret: req.SHOPIFY_CLIENT_SECRET }, json: true });
  await H.httpRequest({ url: `https://${dom}/admin/api/${ver}/products.json?limit=1`, headers: { 'X-Shopify-Access-Token': tok.access_token }, json: true });
  await H.httpRequest({ url: `https://${dom}/admin/api/${ver}/orders.json?status=any&limit=1`, headers: { 'X-Shopify-Access-Token': tok.access_token }, json: true });
  try { const wh = await H.httpRequest({ url: `https://${dom}/admin/api/${ver}/webhooks.json`, headers: { 'X-Shopify-Access-Token': tok.access_token }, json: true }); webhookCount = (wh.webhooks || []).length; } catch (e) { webhookCount = null; }
  return `scopes: ${tok.scope}`;
}));
results.push(await check('openai', async () => {
  if (!req.OPENAI_API_KEY) throw new Error('OPENAI_API_KEY manquant');
  const r = await H.httpRequest({ url: 'https://api.openai.com/v1/models', headers: { Authorization: `Bearer ${req.OPENAI_API_KEY}` }, json: true });
  return `${(r.data && r.data.length) || 0} modeles`;
}));
results.push(await check('telegram', async () => {
  if (!req.TELEGRAM_BOT_TOKEN) throw new Error('TELEGRAM_BOT_TOKEN manquant');
  const r = await H.httpRequest({ url: `https://api.telegram.org/bot${req.TELEGRAM_BOT_TOKEN}/getMe`, json: true });
  if (!r.ok) throw new Error('getMe ok=false');
  return `@${r.result.username}`;
}));
results.push(await check('printful', async () => {
  if (!req.PRINTFUL_API_KEY) throw new Error('PRINTFUL_API_KEY manquant');
  const r = await H.httpRequest({ url: 'https://api.printful.com/stores', headers: { Authorization: `Bearer ${req.PRINTFUL_API_KEY}` }, json: true });
  return `${(r.result && r.result.length) || 0} boutique(s)`;
}));
results.push(await check('supabase', async () => {
  if (!req.SUPABASE_URL || !req.SUPABASE_SERVICE_ROLE_KEY) throw new Error('SUPABASE_URL/SERVICE_ROLE_KEY manquant');
  await H.httpRequest({ url: `${req.SUPABASE_URL}/rest/v1/connection_health?select=service&limit=1`, headers: { apikey: req.SUPABASE_SERVICE_ROLE_KEY, Authorization: `Bearer ${req.SUPABASE_SERVICE_ROLE_KEY}` }, json: true });
  return 'REST + table connection_health OK';
}));
results.push({ service: 'n8n', status: 'ok', detail: 'runtime actif (workflow execute)', latency: 0 });
const green = results.filter((r) => r.status === 'ok').map((r) => `\uD83D\uDFE2 ${r.service} \u2014 ${r.detail}`);
const red = results.filter((r) => r.status === 'error').map((r) => `\uD83D\uDD34 ${r.service} \u2014 ${r.detail}`);
const yellow = [];
if (missingEnv.length) yellow.push(`\uD83D\uDFE1 variables manquantes : ${missingEnv.join(', ')}`);
if (webhookCount === 0) yellow.push('\uD83D\uDFE1 webhooks Shopify : 0 enregistre (MVP en pull quotidien)');
if (webhookCount > 0) green.push(`\uD83D\uDFE2 webhooks Shopify \u2014 ${webhookCount} enregistre(s)`);
let summary = '\uD83D\uDCE1 *Sante des connexions \u2014 African College*\n\n';
if (green.length) summary += green.join('\n') + '\n';
if (yellow.length) summary += yellow.join('\n') + '\n';
if (red.length) summary += red.join('\n') + '\n';
summary += `\nResume : ${green.length} \uD83D\uDFE2 \u00b7 ${yellow.length} \uD83D\uDFE1 \u00b7 ${red.length} \uD83D\uDD34`;
const DELIM = '$cd$';
const esc = (s) => String(s == null ? '' : s).split(DELIM).join('');
const stmts = results.map((r) => `select fn_record_connection_check('${r.service}','${r.status}',${DELIM}${esc(r.detail)}${DELIM},${r.latency | 0});`);
const has_error = red.length > 0;
return [{ json: { sql: stmts.join('\n'), has_error, summary, webhooks: webhookCount } }];
